#!/usr/bin/env node
// Bundles the committed sample CSV fixtures into data/focus/samples/ and
// registers them (with sha256) in data/focus/index.json's `samples` map —
// the only data source calculate_kpi (T-034) is allowed to compute over.
// Sources: the official FOCUS-Sample-Data 1.0 fixture (fetched once by
// fetch-official-sample.mjs) and the deterministic seeded synthetic
// fixtures for 1.0/1.2 (generated by generate-focus-synthetic-samples.mjs).
// No network fetch here — re-run any time after either upstream fixture
// changes; requires a prior `npm run build`.

import { readFileSync } from "node:fs";
import { join } from "node:path";
import { emitIndex, emitSamples } from "../dist/crawlers/focus/emit.js";

const ROOT = join(import.meta.dirname, "..");
const DATA_DIR = join(ROOT, "data/focus");
const FIXTURES_DIR = join(ROOT, "src/crawlers/focus/fixtures/samples");

function rowCount(csvText) {
  return csvText.trimEnd().split("\n").length - 1;
}

function readCsv(rel) {
  return readFileSync(join(FIXTURES_DIR, rel), "utf8");
}

const officialProvenance = JSON.parse(
  readFileSync(join(FIXTURES_DIR, "1.0/PROVENANCE.json"), "utf8"),
);
const official10 = readCsv("1.0/focus_sample.csv");
const synthetic10 = readCsv("synthetic/1.0/focus_synthetic_sample.csv");
const synthetic12 = readCsv("synthetic/1.2/focus_synthetic_sample.csv");

const SYNTHETIC_SEED = 42; // must match generate-focus-synthetic-samples.mjs

const inputs = [
  {
    csvText: official10,
    entry: {
      version: "1.0",
      kind: "official",
      row_count: rowCount(official10),
      license: officialProvenance.license,
      source_url: officialProvenance.url,
      seed: null,
      note:
        "Official FOCUS-Sample-Data 1.0 sample: real, anonymized multi-provider billing data published by the FOCUS project.",
    },
  },
  {
    csvText: synthetic10,
    entry: {
      version: "1.0",
      kind: "synthetic",
      row_count: rowCount(synthetic10),
      license: "CC-BY-4.0",
      source_url: null,
      seed: SYNTHETIC_SEED,
      note:
        "SYNTHETIC: deterministically generated by this project's seeded generator, not real billing data.",
    },
  },
  {
    csvText: synthetic12,
    entry: {
      version: "1.2",
      kind: "synthetic",
      row_count: rowCount(synthetic12),
      license: "CC-BY-4.0",
      source_url: null,
      seed: SYNTHETIC_SEED,
      note:
        "SYNTHETIC: deterministically generated by this project's seeded generator, not real billing data. No official FOCUS 1.2 sample exists anywhere.",
    },
  },
];

function main() {
  const samplesSha = emitSamples(DATA_DIR, inputs);
  const index = JSON.parse(
    readFileSync(join(DATA_DIR, "index.json"), "utf8"),
  );
  emitIndex(DATA_DIR, index.latest, index.versions, index.derived, samplesSha);
  for (const { entry } of inputs) {
    console.error(
      `bundled ${entry.version}/${entry.kind}/focus_sample.csv (${entry.row_count} rows)`,
    );
  }
}

main();
